INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(61263, 0, 0, 'Mortimer, it would appear we have someone here to interrupt our plans!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61263, 1, 0, 'All of our progress, our influence... What a pointless end...', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61264, 0, 0, 'You will not take what is mine!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 30138'),
(61264, 1, 0, 'Father...', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 30139'),
(61418, 0, 0, 'My family has held power in Gilneas for countless generations. You will not change fate.', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61418, 1, 0, 'It... it was pointless after all... This cannot be the way I fall...', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61418, 2, 0, 'Our nation stands strong! I did what was neccesary.', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 81055'),
(61419, 0, 0, 'This district is currently on lockdown!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61419, 1, 0, 'Foolish interloper, you do not belong here...', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61421, 0, 0, 'Order must be maintained!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61421, 1, 0, 'I will not let Gilneas fall to madness, not while I...', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61422, 0, 0, 'I hunt from the shadows, these streets have been cleared by my hand!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61422, 1, 0, 'This was not meant to be...', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61423, 0, 0, 'I have served as Marshal throughout all of the orcish incursions. You will not put an end to Gilneas.', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(61423, 1, 0, 'The brave defenders of this city... will not let you put it to ruin, outsider!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text');
